import React, { useContext, useState } from 'react';
import { NavHashLink as NavLink } from 'react-router-hash-link';
import { IoMenuSharp, IoHomeSharp } from 'react-icons/io5';
import { HiDocumentText } from 'react-icons/hi';
import { BsFillGearFill } from 'react-icons/bs';
import { MdPhone } from 'react-icons/md';
import { FaUser, FaFolderOpen } from 'react-icons/fa';
import { makeStyles } from '@mui/styles'; // Corrected import
import Fade from 'react-reveal/Fade'; // Ensure this is correctly imported
import { Drawer } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close'; // Updated import
import './Navbar.css';
import { ThemeContext } from '../../contexts/ThemeContext';
import { sizeTheme } from '../../contexts/ThemeContext';
import { headerData } from '../../data/headerData';
import mylogo from '../../assets/png/mylogo.png'
// Move makeStyles outside the component to avoid recreating it on every render

const useStyles = makeStyles((t) => ({
    navMenu: {
        fontSize: '2.5rem',
        color: (theme) => theme.tertiary,
        cursor: 'pointer',
        transform: 'translateY(-10px)',
        transition: 'color 0.3s',
        position: "fixed",
        top: "30px",
        right: "30px",
        '&:hover': {
            color: (theme) => theme.primary,
        },
        [sizeTheme.breakpoints.down('sm')]: {
            fontSize: '2.5rem',
        },
        [sizeTheme.breakpoints.down('xs')]: {
            fontSize: '2rem',
        },
    },
    MuiDrawer: {
        padding: '0em 1.8em',
        width: '14em',
        fontFamily: 'var(--primaryFont)',
        fontStyle: 'normal',
        fontWeight: 'normal',
        fontSize: '24px',
        background: (theme) => theme.secondary,
        overflow: 'hidden',
        borderTopRightRadius: '40px',
        borderBottomRightRadius: '40px',
        [sizeTheme.breakpoints.down('sm')]: {
            width: '12em',
        },
    },
    closebtnIcon: {
        fontSize: '2rem',
        fontWeight: 'bold',
        cursor: 'pointer',
        color: (theme) => theme.primary,
        position: 'absolute',
        right: 40,
        top: 40,
        transition: 'color 0.2s',
        '&:hover': {
            color: (theme) => theme.tertiary,
        },
        [sizeTheme.breakpoints.down('sm')]: {
            right: 20,
            top: 20,
        },
    },
    drawerItem: {
        margin: '2rem auto',
        borderRadius: '78.8418px',
        background: (theme) => theme.secondary,
        color: (theme) => theme.primary,
        width: '85%',
        height: '60px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-evenly',
        padding: '0 30px',
        boxSizing: 'border-box',
        border: '2px solid',
        borderColor: (theme) => theme.primary,
        transition: 'background-color 0.2s, color 0.2s',
        '&:hover': {
            background: (theme) => theme.primary,
            color: (theme) => theme.secondary,
        },
        [sizeTheme.breakpoints.down('sm')]: {
            width: '100%',
            padding: '0 25px',
            height: '55px',
        },
    },
    drawerLinks: {
        fontFamily: 'var(--primaryFont)',
        width: '50%',
        fontSize: '1.3rem',
        fontWeight: 600,
        [sizeTheme.breakpoints.down('sm')]: {
            fontSize: '1.125rem',
        },
    },
    drawerIcon: {
        fontSize: '1.6rem',
        [sizeTheme.breakpoints.down('sm')]: {
            fontSize: '1.385rem',
        },
    },
}));

function Navbar() {
    const { theme, setHandleDrawer } = useContext(ThemeContext);

    const [open, setOpen] = useState(false);
    const classes = useStyles(theme);

    const handleDrawerOpen = () => {
        setOpen(true);
        setHandleDrawer();
    };

    const handleDrawerClose = () => {
        setOpen(false);
        setHandleDrawer();
    };

    const shortname = (name) => {
        if (name.length > 12) {
            return name.split(' ')[0];
        } else {
            return name;
        }
    };

    return (
        <div className='navbar'>
            <img src={mylogo} alt='' className='mylogo' />
            <div className='navbar--container'>
                <h1 style={{ color: theme.secondary }}>
                    {shortname(headerData.name)} Addisu
                </h1>

                <IoMenuSharp
                    className={classes.navMenu}
                    onClick={handleDrawerOpen}
                    aria-label='Menu'
                    id='navicon'
                />
            </div>
            <Drawer
                variant='temporary'
                onClose={handleDrawerClose}
                anchor='left'
                open={open}
                classes={{ paper: classes.MuiDrawer }}
                className='drawer'
                disableScrollLock={true}
            >
                <div className='div-closebtn'>
                    <CloseIcon
                        onClick={handleDrawerClose}
                        onKeyDown={(e) => {
                            if (e.key === ' ' || e.key === 'Enter') {
                                e.preventDefault();
                                handleDrawerClose();
                            }
                        }}
                        className={classes.closebtnIcon}
                        role='button'
                        tabIndex='0'
                        aria-label='Close'
                    />
                </div>
                <br />

                <div onClick={handleDrawerClose}>
                    <div className='navLink--container'>
                        <Fade left>
                            <NavLink
                                to='/'
                                smooth={true}
                                spy='true'
                                duration={2000}
                            >
                                <div className={classes.drawerItem}>
                                    <IoHomeSharp
                                        className={classes.drawerIcon}
                                    />
                                    <span className={classes.drawerLinks}>
                                        Home
                                    </span>
                                </div>
                            </NavLink>
                        </Fade>

                        <Fade left>
                            <NavLink
                                to='/#about'
                                smooth={true}
                                spy='true'
                                duration={2000}
                            >
                                <div className={classes.drawerItem}>
                                    <FaUser className={classes.drawerIcon} />
                                    <span className={classes.drawerLinks}>
                                        About
                                    </span>
                                </div>
                            </NavLink>
                        </Fade>

                        <Fade left>
                            <NavLink
                                to='/#education'
                                smooth={true}
                                spy='true'
                                duration={2000}
                            >
                                <div className={classes.drawerItem}>
                                    <HiDocumentText
                                        className={classes.drawerIcon}
                                    />
                                    <span className={classes.drawerLinks}>
                                        Education
                                    </span>
                                </div>
                            </NavLink>
                        </Fade>

                        <Fade left>
                            <NavLink
                                to='/#skills'
                                smooth={true}
                                spy='true'
                                duration={2000}
                            >
                                <div className={classes.drawerItem}>
                                    <BsFillGearFill
                                        className={classes.drawerIcon}
                                    />
                                    <span className={classes.drawerLinks}>
                                        Skills
                                    </span>
                                </div>
                            </NavLink>
                        </Fade>

                        <Fade left>
                            <NavLink
                                to='/#projects'
                                smooth={true}
                                spy='true'
                                duration={2000}
                            >
                                <div className={classes.drawerItem}>
                                    <FaFolderOpen
                                        className={classes.drawerIcon}
                                    />
                                    <span className={classes.drawerLinks}>
                                        Projects
                                    </span>
                                </div>
                            </NavLink>
                        </Fade>

                        <Fade left>
                            <NavLink
                                to='/#contacts'
                                smooth={true}
                                spy='true'
                                duration={2000}
                            >
                                <div className={classes.drawerItem}>
                                    <MdPhone className={classes.drawerIcon} />
                                    <span className={classes.drawerLinks}>
                                        Contact
                                    </span>
                                </div>
                            </NavLink>
                        </Fade>
                    </div>
                </div>
            </Drawer>
        </div>
    );
}

export default Navbar;
